ALTER TABLE conversation_participants ADD kind ENUM('customer','agent','support','collaborator') NOT NULL DEFAULT 'customer';
UPDATE conversation_participants cp JOIN conversations c ON c.id=cp.conversation_id JOIN listings l ON l.id=c.listing_id SET cp.kind='agent' WHERE cp.user_id=l.agent_id;
CREATE TABLE price_change_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, requested_minor BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, status ENUM('requested','approved','rejected') DEFAULT 'requested', reviewed_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE service_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, category VARCHAR(100) NOT NULL, details TEXT NOT NULL, status ENUM('pending','approved','rejected','archived') DEFAULT 'pending', reviewed_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE business_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB;
INSERT INTO business_settings VALUES ('business_name','Aurelle Estates'),('contact_note','Connect through your Aurelle account.'),('footer_description','Exceptional homes. A more considered way to find yours.');
